CREATE TABLE "case_documents" ("id" TEXT NOT NULL, "case_id" TEXT NOT NULL, "uploaded_by_user_id" TEXT NOT NULL, "kind" "DocumentKind" NOT NULL, "original_filename" TEXT NOT NULL, "storage_key" TEXT NOT NULL, "content_type" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "sha256" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "case_documents_pkey" PRIMARY KEY ("id"));
