CREATE TABLE "protocol_templates" ("id" TEXT NOT NULL, "establishment_id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "is_active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "protocol_templates_pkey" PRIMARY KEY ("id"));
