CREATE TABLE "protocol_versions" ("id" TEXT NOT NULL, "protocol_template_id" TEXT NOT NULL, "version" INTEGER NOT NULL, "title" TEXT NOT NULL, "content" JSONB NOT NULL, "status" "ProtocolVersionStatus" NOT NULL DEFAULT 'BORRADOR', "created_by_user_id" TEXT NOT NULL, "published_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "protocol_versions_pkey" PRIMARY KEY ("id"));
