CREATE UNIQUE INDEX "case_protocol_applications_case_id_protocol_version_id_key" ON "case_protocol_applications"("case_id", "protocol_version_id");
CREATE TABLE "case_measures" ("id" TEXT NOT NULL, "case_id" TEXT NOT NULL, "created_by_user_id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "due_at" TIMESTAMP(3), "status" "MeasureStatus" NOT NULL DEFAULT 'PENDIENTE', "version" INTEGER NOT NULL DEFAULT 1, "completed_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "case_measures_pkey" PRIMARY KEY ("id"));
