CREATE TABLE "case_follow_ups" ("id" TEXT NOT NULL, "case_id" TEXT NOT NULL, "created_by_user_id" TEXT NOT NULL, "occurred_at" TIMESTAMP(3) NOT NULL, "note" TEXT NOT NULL, "next_action" TEXT, "next_action_due_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "case_follow_ups_pkey" PRIMARY KEY ("id"));
