CREATE TABLE "case_tasks" ("id" TEXT NOT NULL, "case_id" TEXT NOT NULL, "created_by_user_id" TEXT NOT NULL, "assigned_to_user_id" TEXT, "title" TEXT NOT NULL, "due_at" TIMESTAMP(3), "status" "TaskStatus" NOT NULL DEFAULT 'PENDIENTE', "completed_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "case_tasks_pkey" PRIMARY KEY ("id"));
CREATE INDEX "case_tasks_case_id_status_due_at_idx" ON "case_tasks"("case_id", "status", "due_at");
CREATE INDEX "case_tasks_assigned_to_user_id_status_due_at_idx" ON "case_tasks"("assigned_to_user_id", "status", "due_at");
CREATE TABLE "notifications" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "case_id" TEXT, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "read_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_pkey" PRIMARY KEY ("id"));
